    using void_t = void;

    template<typename U, typename V>
    void_t<decltype(
        (std::declval<U>().*std::declval<V>())()
    )> boom(){}

    struct Foo {
        void bar(){}
    };

    int main() {
        boom<Foo, decltype(&Foo::bar)>();
    }

