int main ()
{
  return Check ("World") ? 0 : 1;
}

./cc1plus -quiet -fmodule-header   bug_a.ii && ./cc1plus -quiet -fmodules-ts bug_b.ii && ./cc1plus -quiet -fmodules-ts bug_c.ii
In module imported at bug_c.ii:1:1:
