| Bugzilla Link | [20370](https://llvm.org/bz20370) |
| Version | 3.4 |
| OS | Linux |
| Attachments | [Clang will hang while this file with -O2](https://user-images.githubusercontent.com/60944935/143749772-bdca7c4b-a1f4-48d1-a964-9e97a00421a4.gz) |
| Reporter | LLVM Bugzilla Contributor |
| CC | @DougGregor,@zygoloid |

## Extended Description 


Compiling the attached .cpp file causes clang to hang when using -O2 and above (at least 8 minutes on my machine). It could be related to bug 18898 since the file contains switch statements, but this file is very small in comparison with only 42 cases (vs. tens of thousands). I tried to reduce the code as much as I could, but if I remove any more, the file compiles fine in no time at all.

> clang --version
clang version 3.4.2 (tags/RELEASE_34/dot2-final)
Target: x86_64-unknown-linux-gnu
Thread model: posix

Command to cause the hang:
clang -Wall -c -O2 optimizerhang.cpp

--- Comment #1 by wheatman at 2023-08-12T03:48:16Z ---
This seems to have been fixed for 3.5
https://godbolt.org/z/os6jxYbP3

As a note I was only able to trigger the long build with an assertion build of the compiler, but this may be due to slightly different versions of clang that the assertion and non assertion builds were using 


code
```
#include <stddef.h>
#include <stdint.h>

enum ValueType
{
	TYPE_INT,
	TYPE_UINT,
	TYPE_LONG,
	TYPE_ULONG,
	TYPE_FLOAT,
	TYPE_DOUBLE
};


union Value
{
	Value(): mInt(0) {}

	int32_t mInt;
	uint32_t mUInt;
	int64_t mLong;
	uint64_t mULong;
	float mFloat;
	double mDouble;

	struct
	{
		const char *buffer;
		size_t length;
	} mString;
};


Value CastValue(const Value &value, ValueType sourceType, ValueType destType)
{
	Value resultValue;

	switch (destType)
	{
		case TYPE_INT:
			switch (sourceType)
			{
				case TYPE_INT:
					resultValue.mInt = int32_t(value.mInt);
					break;
				case TYPE_UINT:
					resultValue.mInt = int32_t(value.mUInt);
					break;
				case TYPE_LONG:
					resultValue.mInt = int32_t(value.mLong);
					break;
				case TYPE_ULONG:
					resultValue.mInt = int32_t(value.mULong);
					break;
				case TYPE_FLOAT:
					resultValue.mInt = int32_t(value.mFloat);
					break;
				case TYPE_DOUBLE:
					resultValue.mInt = int32_t(value.mDouble);
					break;
			}
			break;

		case TYPE_UINT:
			switch (sourceType)
			{
				case TYPE_INT:
					resultValue.mUInt = uint32_t(value.mInt);
					break;
				case TYPE_UINT:
					resultValue.mUInt = uint32_t(value.mUInt);
					break;
				case TYPE_LONG:
					resultValue.mUInt = uint32_t(value.mLong);
					break;
				case TYPE_ULONG:
					resultValue.mUInt = uint32_t(value.mULong);
					break;
				case TYPE_FLOAT:
					resultValue.mUInt = uint32_t(value.mFloat);
					break;
				case TYPE_DOUBLE:
					resultValue.mUInt = uint32_t(value.mDouble);
					break;
			}
			break;

		case TYPE_LONG:
			switch (sourceType)
			{
				case TYPE_INT:
					resultValue.mLong = int64_t(value.mInt);
					break;
				case TYPE_UINT:
					resultValue.mLong = int64_t(value.mUInt);
					break;
				case TYPE_LONG:
					resultValue.mLong = int64_t(value.mLong);
					break;
				case TYPE_ULONG:
					resultValue.mLong = int64_t(value.mULong);
					break;
				case TYPE_FLOAT:
					resultValue.mLong = int64_t(value.mFloat);
					break;
				case TYPE_DOUBLE:
					resultValue.mLong = int64_t(value.mDouble);
					break;
			}
			break;

		case TYPE_ULONG:
			switch (sourceType)
			{
				case TYPE_INT:
					resultValue.mULong = uint64_t(value.mInt);
					break;
				case TYPE_UINT:
					resultValue.mULong = uint64_t(value.mUInt);
					break;
				case TYPE_LONG:
					resultValue.mULong = uint64_t(value.mLong);
					break;
				case TYPE_ULONG:
					resultValue.mULong = uint64_t(value.mULong);
					break;
				case TYPE_FLOAT:
					resultValue.mULong = uint64_t(value.mFloat);
					break;
				case TYPE_DOUBLE:
					resultValue.mULong = uint64_t(value.mDouble);
					break;
			}
			break;

		case TYPE_FLOAT:
			switch (sourceType)
			{
				case TYPE_INT:
					resultValue.mFloat = float(value.mInt);
					break;
				case TYPE_UINT:
					resultValue.mFloat = float(value.mUInt);
					break;
				case TYPE_LONG:
					resultValue.mFloat = float(value.mLong);
					break;
				case TYPE_ULONG:
					resultValue.mFloat = float(value.mULong);
					break;
				case TYPE_FLOAT:
					resultValue.mFloat = float(value.mFloat);
					break;
				case TYPE_DOUBLE:
					resultValue.mFloat = float(value.mDouble);
					break;
			}
			break;


		case TYPE_DOUBLE:
			switch (sourceType)
			{
				case TYPE_INT:
					resultValue.mDouble = double(value.mInt);
					break;
				case TYPE_UINT:
					resultValue.mDouble = double(value.mUInt);
					break;
				case TYPE_LONG:
					resultValue.mDouble = double(value.mLong);
					break;
				case TYPE_ULONG:
					resultValue.mDouble = double(value.mULong);
					break;
				case TYPE_FLOAT:
					resultValue.mDouble = double(value.mFloat);
					break;
				case TYPE_DOUBLE:
					resultValue.mDouble = double(value.mDouble);
					break;
			}
			break;
	}

	return resultValue;
}

