          }
       }
       ++idx;
    }
    std::abort();
}



struct MyStruct
{
   void fun1(int /*a*/) {}

   int fun2(char /*b*/, short /*c*/, bool /*d*/) { return 0; }

};



template <>
constexpr auto get_member_functions<MyStruct>()
