-     && TREE_CODE (TREE_TYPE (x)) != REFERENCE_TYPE)
+     && TREE_CODE (TREE_TYPE (x)) != REFERENCE_TYPE
+     && !TYPE_PTRDATAMEM_P (TREE_TYPE (x)))
    {
      tree v = decl_constant_value (x);
      if (v != x && v != error_mark_node)


fixes the original testcase, as well as the one Comment 4 and in Comment 11.

