Description:
The following code got accepted by Clang 10.0 and MSVC 19.27.29112, yet fails to compile under GCC:

template <class ...Ts>
class foo : public Ts...{
public:
    template <typename T, typename ...Us>
    explicit foo(T &&t, Us &&...us)
        //: Ts(Ts(t, us))...{} -> This line is accepted
        //: Ts{t, us...}...{} -> This line is accepted too
        : Ts(t, us...)...{} // This line is rejected
};

class bar{
public:
    explicit bar(int){}
};

class qux{
public:
    explicit qux(int){}
};

class baz{
public:
    explicit baz(int){}
};

int main(){
    foo<bar, baz, qux> x(3);
    (void)x;
    return 0;
}

